// Zwei Fragen in einem Lauf:
//  Gruppe 1  weitere Namen fuer den Versatz
//  Gruppe 2  Schreibweise des Filters auf Angebot beziehungsweise Buchung
// Erkennungszeichen: sinkt gemeldet_total unter 4038, wurde der Filter angenommen.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2/booking/list';

function auswerten(body) {
  const roh = body?.data;
  const liste = roh && typeof roh === 'object' && !Array.isArray(roh) ? Object.entries(roh) : [];
  const eintraege = liste.map(([k, v]) => (v && typeof v === 'object' ? v : { id: k }));
  const l = body?.limit ?? {};
  return {
    anzahl: liste.length,
    gemeldet_start: l.start ?? '-',
    gemeldet_reply: l.reply ?? '-',
    gemeldet_total: l.total ?? '-',
    erste_id: eintraege[0]?.id ?? null,
    erstes_angebot: eintraege[0]?.offer ?? null,
  };
}

async function abruf(bezeichnung, qs) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: 'GET',
      url: basis,
      headers,
      qs,
      json: true,
      returnFullResponse: true,
      timeout: 60000,
    });
    return { variante: bezeichnung, status: antwort.statusCode, ...auswerten(antwort.body) };
  } catch (fehler) {
    return {
      variante: bezeichnung,
      status: fehler?.response?.status ?? fehler?.httpCode ?? 'kein Status',
      anzahl: 0,
      fehlermeldung: String(fehler?.message ?? fehler).slice(0, 160),
    };
  }
}

const hole = abruf.bind(this);

// Vergleichsabruf, liefert zugleich eine echte Buchungs- und Angebots-ID.
const vergleich = await hole('A Vergleich limit 10', { limit: 10 });
const buchungId = vergleich.erste_id;
const angebotId = vergleich.erstes_angebot;

const gruppe1 = [
  ['B limitstart', { limit: 10, limitstart: 100 }],
  ['C startlimit', { limit: 10, startlimit: 100 }],
  ['D start_limit', { limit: 10, start_limit: 100 }],
  ['E next', { limit: 10, next: 100 }],
  ['F after', { limit: 10, after: 100 }],
  ['G cursor', { limit: 10, cursor: 100 }],
  ['H limit als Paar', { limit: '100:10' }],
  ['I reply und start', { reply: 10, start: 100, limit: 10 }],
];

const gruppe2 = angebotId
  ? [
      ['J filter Klammer Angebot', { limit: 10, 'filter[offer.id]': angebotId }],
      ['K filter Punkt Angebot', { limit: 10, 'filter.offer.id': angebotId }],
      ['L filter Pfeil Angebot', { limit: 10, 'filter>offer.id': angebotId }],
      ['M offer.id direkt', { limit: 10, 'offer.id': angebotId }],
      ['N offer direkt', { limit: 10, offer: angebotId }],
      ['O filter als JSON', { limit: 10, filter: JSON.stringify({ 'offer.id': angebotId }) }],
    ]
  : [];

const gruppe3 = buchungId
  ? [
      ['P filter Klammer Buchung', { 'filter[id]': buchungId }],
      ['Q id direkt', { id: buchungId }],
      ['R filter Punkt Buchung', { 'filter.id': buchungId }],
    ]
  : [];

const ergebnisse = [vergleich];
for (const [bezeichnung, qs] of [...gruppe1, ...gruppe2, ...gruppe3]) {
  ergebnisse.push(await hole(bezeichnung, qs));
}

return ergebnisse.map((e) => ({
  json: {
    schritt: 'S9',
    variante: e.variante,
    status: e.status,
    anzahl: e.anzahl,
    gemeldet_start: e.gemeldet_start ?? '-',
    gemeldet_total: e.gemeldet_total ?? '-',
    filter_wirkt: e.gemeldet_total && e.gemeldet_total !== '-' && e.gemeldet_total < 4038 ? 'JA' : 'nein',
    versatz_wirkt: e.erste_id && buchungId ? (e.erste_id !== buchungId ? 'JA' : 'nein') : '-',
    fehlermeldung: e.fehlermeldung ?? '-',
  },
}));
